<?php session_start();require __DIR__.'/../config/database.php';require __DIR__.'/../includes/helpers.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status']==='blocked'?'blocked':'active';$pdo->prepare('UPDATE users SET status=? WHERE id=? AND id<>?')->execute([$status,$id,$_SESSION['user']['id']]);flash('success','Đã cập nhật trạng thái.');redirect('admin/users.php');}$rows=$pdo->query('SELECT id,full_name,email,role,status,created_at FROM users ORDER BY id DESC')->fetchAll();$pageTitle='Admin · Users';include __DIR__.'/../includes/header.php';show_flash();?><div class="container py-5"><h1 class="fw-800">Users</h1><div class="table-responsive mt-4"><table class="table align-middle"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['full_name']) ?></strong><div class="small text-secondary"><?= e($r['email']) ?></div></td><td><?= e($r['role']) ?></td><td><?= e($r['status']) ?></td><td><?= e($r['created_at']) ?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= $r['id'] ?>"><input type="hidden" name="status" value="<?= $r['status']==='active'?'blocked':'active' ?>"><button class="btn btn-sm btn-outline-dark"><?= $r['status']==='active'?'Block':'Activate' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div><?php include __DIR__.'/../includes/footer.php'; ?>
